CREATE TABLE `note`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '번호',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '제목',
  `body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
